{
  "claims": [
    {
      "anchor": "WAL mode first appeared in SQLite 3.7.0",
      "claim_text": "WAL mode first appeared in SQLite version 3.7.0.",
      "kind": "version",
      "sure": true,
      "evidence": [
        {"sid": "P4.S1", "rel": "entails"}
      ],
      "check": {"kind": "version", "left": "3.7.0", "op": ">=", "right": "3.7.0"},
      "reasoning": "Passage states WAL available beginning with 3.7.0."
    },
    {
      "anchor": "journal_mode=WAL is persistent",
      "claim_text": "journal_mode=WAL is persistent.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Direct restatement of P2.S0."
    },
    {
      "anchor": "simply closing and reopening a WAL database is not enough to change its page size",
      "claim_text": "Closing and reopening a WAL database is not enough to change its page size.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P2.S1", "rel": "entails"},
        {"sid": "P0.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Reopen stays WAL; page_size cannot change in WAL mode."
    },
    {
      "anchor": "you have to switch back to a rollback journal mode first",
      "claim_text": "To change the page size, one must switch back to a rollback journal mode first.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P0.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P0.S1 states must be in rollback journal mode to change page size."
    },
    {
      "anchor": "From version 3.7.0 until 3.22.0, reading a WAL-mode database required write access",
      "claim_text": "From version 3.7.0 until 3.22.0, reading a WAL-mode database required write access.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P3.S1", "rel": "entails"},
        {"sid": "P3.S2", "rel": "entails"},
        {"sid": "P4.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "WAL from 3.7.0; write access required until relaxed at 3.22.0."
    },
    {
      "anchor": "SQLite's default page size is 4096 bytes",
      "claim_text": "SQLite's default page size is 4096 bytes.",
      "kind": "direct",
      "sure": false,
      "evidence": [],
      "check": null,
      "reasoning": "No passage mentions default page size."
    },
    {
      "anchor": "Converting a database to WAL fails if the VFS does not support the necessary shared-memory primitives",
      "claim_text": "Converting a database to WAL fails if the VFS does not support the necessary shared-memory primitives.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P1.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P1.S2 gives this as an example of failed conversion."
    },
    {
      "anchor": "in which case the journal_mode pragma returns an error",
      "claim_text": "If conversion to WAL fails, the journal_mode pragma returns an error.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S2", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "P1.S2 says it returns the prior journaling mode string, not an error."
    }
  ]
}
